style.css:
* {
    --color-bg-toolbar-selected: rgba(0,0,0,0.3);
    --color-bgtoolbarmodeswitcher: rgba(0,0,0,0.3);
    --color-bg-hover: rgba(0,0,0,0.5);
    --color-icon-brand: rgba(255,255,255,1);
    --color-bgtoolbarmodeswitcher-hover: rgba(0,0,0,0.3);
    --color-bg-tertiary: rgba(0,0,0,0.5);
    --color-border: rgba(255,255,255,0.3);
}

div[class*="positioned_design_toolbelt"] {
    bottom: 72px;
}
div[role="toolbar"][aria-orientation="horizontal"][aria-label="Editor"]::after {
    content: 'Jakub Kučera';
    font: 0/0 a;
    position: absolute;
    top: 50%;
    left: -5%;
    right: 0px;
    width: 110%;
    padding-top: 25%;
    transform: translateY(-50.5%);
    background-image: url('https://i.ibb.co/NntZSndK/kitkat.png') !important;
    background-size: 100% auto;
    background-position: center center;
    background-color: transparent !important;
    background-repeat: no-repeat;
    z-index: 1;
    pointer-events: none;
}
div[role="toolbar"][aria-orientation="horizontal"][aria-label="Editor"] > div {
    position: relative;
    z-index: 2;
}
div[class*="toolbelt_mode_segmented_control--selected"] {
    background-color: var(--color-bg-toolbar-selected);
}
div[role="toolbar"][aria-orientation="horizontal"]:not([aria-label="Editor"]) > div > div:not(:empty):not([data-fpl-component*="primitive"])::after {
    content: 'Jakub Kučera';
    font: 0/0 a;
    position: absolute;
    top: 50%;
    left: -5%;
    right: 0px;
    width: 110%;
    padding-top: 25%;
    transform: translateY(-50.5%);
    background-image: url('https://i.ibb.co/NntZSndK/kitkat.png') !important;
    background-size: 100% auto;
    background-position: center center;
    background-color: transparent !important;
    background-repeat: no-repeat;
    z-index: 1;
    pointer-events: none;
}
div[role="toolbar"][aria-orientation="horizontal"]:not([aria-label="Editor"]) > div > div {
    position: relative;
    z-index: 2;
    overflow: visible;
}
div[role="toolbar"][aria-orientation="horizontal"]:not([aria-label="Editor"]) > div > div > * {
    position: relative;
    z-index: 3;
}
div[role="toolbar"][aria-orientation="horizontal"]:not([aria-label="Editor"]) > div > div > * button {
    background: var(--color-bg-toolbar-selected);
    border-color: transparent;
}
div[class*="drawing_tools--toolBackground"] {
    background: var(--color-bg-toolbar-selected);
    border-color: var(--color-border);
}
label[class*="slider_combo_input--scrubbable"], div[class*="slider_combo_input--sliderContainer"] {
    background: var(--color-bg-toolbar-selected);
    border-color: transparent;
}
